function PVPArenaAgainstDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        ---@type PVPArenaEntryDojo
        local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
        local isAudience   = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience
        self.isAudience = isAudience
        self:RefreshButtonGroup(isAudience)

        self:RefreshTineLineNode()

        local argument   = self.controller.Argument
        local parameters = argument.parameters
        if parameters.groupIndex then
            self.groupIndex = parameters.groupIndex
            parameters.groupIndex = nil
        end

        local matchChartType = self:GetSelectMatchChartType()
        self:RefreshMatchChartByType(matchChartType)

        self.__EventRequestHomeSuccess          = Events.AddListener(Constants.EventNames.PVPArenaRequestHomeSuccess, Bind(self, self.OnEventRequestHomeSuccess))
    end))
    return coWait
end

function PVPArenaAgainstDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.__EventRequestHomeSuccess then
            Events.RemoveListener(Constants.EventNames.PVPArenaRequestHomeSuccess, self.__EventRequestHomeSuccess)
            self.__EventRequestHomeSuccess = nil
        end
        if not self.isBack then
            local argument   = self.controller.Argument
            local parameters = argument.parameters
            parameters.matchChartType = self.selectMatchChartType
            local gameObject = self.matchChartGos[MatchChartType.Group]
            if gameObject then
                ---@type PVPArenaGroupMatchChart
                local env = CfUtils.GetLuaScr(gameObject, MatchChartEnvPath[MatchChartType.Group])
                if not isNull(env) then
                    parameters.groupIndex = env:GetGroupIndex()
                end
            end
        end
        self.navigatorEnv:SetCustomBackHandlerAction()
        self.navigatorEnv = nil
        self:ReleaseBundle()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

