function PVPArenaAgainstDialog:RefreshTineLineNode()
    ---@type PVPArenaTimeLineNode
    local mbEnv = CfUtils.GetLuaScr(self.PVPTimeLineNode.gameObject, PVPArenaTimeLineNodePath)
    if mbEnv == nil then return end

    mbEnv:RefreshUI()
end

function PVPArenaAgainstDialog:RefreshButtonGroup(isAudience)
    KTool.SetActive(self.ButtonTicket.gameObject, isAudience)
    if isAudience then
        local pvpArenaDojo = pvpArenaComponent:GetPVPArenaDojo()
        local quizzed       = checkTable(pvpArenaDojo.quizzed)
        --- 投过几次票
        local quizNum       = table.count(quizzed)
        --- 竞猜票数量
        local quizTicketNum = checkNumber(pvpArenaDojo.quizTicketNum)
        --- 能投多少次
        local quizMaxNum    = quizNum + quizTicketNum
        self.ButtonTicketText.text = string.format("%s/%s", quizNum, quizMaxNum)
    end
end

---RefreshMatchChartByType
---根据类型刷新对阵图
---@param matchChartType number
function PVPArenaAgainstDialog:RefreshMatchChartByType(matchChartType)
    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    KTool.SetActive(self.ButtonHere.gameObject, not self.isAudience and matchChartType == MatchChartType.Group and seasonFlag ~= Constants.PVPArenaSeasonFullStatus.Closed)

    local oldMatchChartType = self.selectMatchChartType
    if oldMatchChartType and oldMatchChartType ~= matchChartType then
        local gameObject = self.matchChartGos[oldMatchChartType]
        if gameObject then
            KTool.SetActive(gameObject, false)
            self:RemoveMatchChartAgainstStateCo(gameObject, matchChartType)
        end
    end
    self.selectMatchChartType = matchChartType
    self:LoadMatchChartByType(matchChartType)
end

---LoadMatchChartByType
---根据类型加载对阵图
---@param matchChartType number
function PVPArenaAgainstDialog:LoadMatchChartByType(matchChartType)
    local gameObject = self.matchChartGos[matchChartType]
    if gameObject then
        KTool.SetActive(gameObject, true)
        self:RefreshMatchChartEnvByType(gameObject, matchChartType)
        return
    end
    local path = MatchChartPath[matchChartType]
    Blocker:AddCondition(path)
    cs_coroutine.start(function()
        local go = GameUtils.LoadBundleAsync(path, self.Root.gameObject, nil, true)
        self.matchChartGos[matchChartType] = go
        -- self.matchChartLoaders[matchChartType] = loader
        self:RefreshMatchChartEnvByType(go, matchChartType)
        Blocker:RemoveCondition(path)
    end)
end

---RefreshMatchChartEnvByType
---根据对战图类型刷新对应的lua环境
---@param gameObject UnityEngine.GameObject
---@param matchChartType number
function PVPArenaAgainstDialog:RefreshMatchChartEnvByType(gameObject, matchChartType)
    local env = CfUtils.GetLuaScr(gameObject, MatchChartEnvPath[matchChartType])
    if isNull(env) then return end
    xTry(function()

        local argument   = self.controller.Argument
        local parameters = argument.parameters
        local isFirst    = parameters.isFirst
        local isGroup = matchChartType == MatchChartType.Group
        if not self.isAudience and isFirst and isGroup then
            env:JumpPlayerGroup()
            parameters.isFirst = false
        else
            if isGroup and self.groupIndex then
                env:SetGroupIndex(self.groupIndex)
            end
            env:RefreshUI()
        end

    end, function()
        printError("%s", debug.traceback())
    end)
end

function PVPArenaAgainstDialog:RemoveMatchChartAgainstStateCo(gameObject, matchChartType)
    local env = CfUtils.GetLuaScr(gameObject, MatchChartEnvPath[matchChartType])
    if isNull(env) then return end
    env:RemoveAgainstStateCo()
end

