function PVPArenaAgainstDialog:GetSelectMatchChartType()
    local oldSeasonFlag = pvpArenaComponent:GetOldSeasonFlag()
    local seasonFlag    = pvpArenaComponent:GetSeasonFlag()
    local selectMatchChartType
    --- 如果是再对阵图界面刷新 的 话 要么是切换导致的刷新 要么是 刷新当前对阵图
    --- 如果切换对阵图
    if oldSeasonFlag == Constants.PVPArenaSeasonFullStatus.OffSeason and seasonFlag == Constants.PVPArenaSeasonFullStatus.Final then
        selectMatchChartType = MatchChartType.Final
    elseif self.selectMatchChartType then
        selectMatchChartType = self.selectMatchChartType
    --- 否则 使用参数
    else
        local argument      = self.controller.Argument
        local parameters    = argument.parameters
        selectMatchChartType = parameters.matchChartType
    end

    return selectMatchChartType
end
