function PVPArenaAgainstDialog:OnEventRequestHomeSuccess()
    self:RefreshTineLineNode()
    local matchChartType = self:GetSelectMatchChartType()
    self:RefreshMatchChartByType(matchChartType)
end

function PVPArenaAgainstDialog:OnCustomBackHandlerAction()
    self.isBack = true

    local UIModule      = CS.Engine.UI.UIModule
    UIModule.BackDialog()
end

function PVPArenaAgainstDialog:OnClickButtonHereAction()
    --- 如果玩家进入最终赛 则提示 "您已经进入最终赛了"
    local mainPanelStatus = pvpArenaComponent:GetMainPanelStatus()
    local seasonFlag      = pvpArenaComponent:GetSeasonFlag()
    if mainPanelStatus ~= Constants.PVPArenaMainPanelStatus.WatchTheMatch and seasonFlag == Constants.PVPArenaSeasonFullStatus.Final then
        GameUtils.Toast(localize("您已经进入最终赛了"))
        return
    end

    local gameObject = self.matchChartGos[MatchChartType.Group]
    if gameObject then
        ---@type PVPArenaGroupMatchChart
        local env = CfUtils.GetLuaScr(gameObject, MatchChartEnvPath[MatchChartType.Group])
        env:JumpPlayerGroup()
    end
end

function PVPArenaAgainstDialog:OnClickButtonTicketAction()
    PVPArenaUtils.ShowQuizListDialog(ExcludeDialogs)
end

function PVPArenaAgainstDialog:OnClickButtonRewardAction()
    PVPArenaUtils.ShowRankRewardDialog(ExcludeDialogs)
end

function PVPArenaAgainstDialog:OnClickButtonHistoryAction()
